packet_css:
@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;600&family=IBM+Plex+Mono&family=Manrope:wght@600&display=swap');
:root{--paper:#FAF9F5;--ink:#141413;--soft:#6B6A66;--line:rgba(20,20,19,.12);--accent:#C4603C;--wait:#946000}
body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 Figtree,system-ui,sans-serif}
main{max-width:860px;margin:0 auto;padding:32px 28px}
h1{font:600 26px/1.2 Manrope,system-ui,sans-serif;margin:4px 0}
h2{font:600 16px/1.3 Manrope,system-ui,sans-serif;margin:26px 0 10px}
.kicker{font:600 11px/1 Figtree,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);margin:0}
.meta{color:var(--soft);font-size:12.5px}
.warn{border:1.5px solid var(--accent);border-radius:10px;padding:10px 14px;font-weight:600}
.who,.finding{display:grid;grid-template-columns:300px 1fr;gap:16px;border-top:1px solid var(--line);padding:14px 0}
.stills{display:flex;gap:6px;flex-wrap:wrap}
figure{margin:0;width:96px}figure img{width:96px;height:72px;object-fit:cover;border-radius:6px;display:block}
figcaption,.t,.hash{font-family:'IBM Plex Mono',monospace;font-size:11.5px}
td.t{white-space:nowrap}
.hash{word-break:break-all}
table{width:100%;border-collapse:collapse;font-size:12.5px}th,td{text-align:left;vertical-align:top;border-top:1px solid var(--line);padding:6px 8px 6px 0}
.empty{color:var(--soft)}
.foot{max-width:860px;margin:0 auto 32px;padding:0 28px;color:var(--soft);font-size:12px}
@media print{body{background:#fff}main{padding:0}.who,.finding{break-inside:avoid}}
